import numpy as np
from scipy.optimize import minimize

def objective(a):
    return np.sum(a**4) + 4*np.sum(a**3) - 756

def constraint1(a):
    return np.sum(a)

def constraint2(a):
    return np.sum(a**2) - 12

cons = [{'type': 'eq', 'fun': constraint1},
        {'type': 'eq', 'fun': constraint2}]

# Try multiple starting points
best_f = float('inf')
for _ in range(10):
    a0 = np.random.uniform(-4, 4, 4)
    res = minimize(objective, a0, constraints=cons)
    if res.success:
        if res.fun < best_f:
            best_f = res.fun
            print(f"New best: {best_f} with {res.x}")

print(f"Final best: {best_f}")
